record.field:

DAY = datetime.datetime.today().day

def _cron_crm_email():

  output = {
            "passed recs": [], 
            "Prospects": [],
            "VCO": [],
            "count": 0,
            "emails created": 0

 }
  slackers = {}
  temp = []

  if DAY != 5 and DAY != 20:
     return

  else:

    prospect = model.env.ref("crm.stage_lead1")
    vco = model.env.ref("crm.stage_lead2")
    leads_prosvco = model.search([("stage_id", "in", [1, 2]), ('opt_email', '!=', False)])
    mail = env["mail.mail"]
    pros_template = env.ref("achosa.crm_prospect_email")
    vco_template = env.ref("achosa.crm_VCO_email")

    for lead in leads_prosvco:
        if not lead.opt_email:
          output['passed recs'].append(lead)
          for rec in output['passed recs']:
            if rec.user_id.login in slackers:
              temp.append(rec)

          for key in slackers:
            slackers[key] = len(slackers[key])
        if DAY == 5 and lead.stage_id.id == 1:
          output["Prospects"].append(lead)
        elif DAY == 20 and lead.stage_id.id == 2:
          output["VCO"].append(lead)

    for rec in output["Prospects"]:
      output["count"] += 1
      pros_template.send_mail(rec.id)
      output["emails created"] += 1

    for rec in output["VCO"]:
      output["count"] += 1
      vco_template.send_mail(rec.id)
      output["emails created"] += 1

    log(str(output))
    log(str(temp))
    log(str(slackers))

_cron_crm_email()


